/**
 * The Tamagui config for the cyclone-ui.
 *
 * @see https://tamagui.dev/docs/core/configuration
 */
export const config: ReturnType<typeof createTamagui> = createTamagui({
  animations,
  tokens,
  themes,
  fonts: {
    body: bodyFont,
    caption: captionFont,
    code: codeFont,
    display: displayFont,
    editorial: editorialFont,
    eyebrow: eyebrowFont
  },
  defaultFont: "body",
  ...userConfig,
  settings: {
    styleValueSyntax: "string",
    ...(userConfig.settings ?? {})
  } as Parameters<typeof createTamagui>[0]["settings"]
});

export type AppConfig = typeof config & {
  tokens: typeof tokens;
  themes: typeof themes;
};

declare module "@tamagui/core" {
  // eslint-disable-next-line @typescript-eslint/no-empty-object-type
  interface TamaguiCustomConfig extends AppConfig {}
}

export default config;

for (const scheme of ["light", "dark"]) {
  const all = config.themes as Record<string, Record<string, unknown>>;
  const root = all[scheme];
  const base = all[`${scheme}_base`];
  if (root && base) {
    for (const key of Object.keys(base)) {
      if (!(key in root)) {
        root[key] = base[key];
      }
    }
  }
}
